package com.dorm.platform.stay.service;

import com.dorm.platform.common.*;
import com.dorm.platform.security.*;
import com.dorm.platform.notice.service.NoticeService;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.time.*;
import java.util.*;
import static com.dorm.platform.common.Input.*;
import static com.dorm.platform.common.BizException.require;

@Service
public class StayService {
 private final SqlStore db; private final DataScope scope; private final NoticeService notice;
 public StayService(SqlStore db,DataScope scope,NoticeService notice){this.db=db;this.scope=scope;this.notice=notice;}
 @Transactional public void lockBatch(CurrentUser u,long batchId){role(u,"DORM_MANAGER");for(var a:db.rows("SELECT application_id FROM stay_application WHERE batch_id=? AND current_status='PENDING_REVIEW' AND "+scope.buildingFilter(u,"building_id")+" ORDER BY application_id FOR UPDATE",batchId))lock(u,id(a.get("application_id")),true);}
 public List<Map<String,Object>> batches(CurrentUser u){role(u,"STUDENT","DORM_MANAGER","ADMIN");if(u.role().equals("STUDENT"))return db.rows("SELECT b.*,r.building_id,r.application_deadline student_deadline,r.auto_lock FROM stay_batch b JOIN stay_building_rule r ON r.batch_id=b.batch_id JOIN v_accommodation_current a ON a.building_id=r.building_id WHERE a.student_user_id=? AND b.current_status='OPEN' ORDER BY b.batch_id DESC",u.id());return db.rows("SELECT * FROM stay_batch ORDER BY batch_id DESC");}
 public List<Map<String,Object>> list(CurrentUser u){role(u,"STUDENT","DORM_MANAGER","ADMIN");String filter=u.role().equals("STUDENT")?"a.student_user_id="+u.id():scope.buildingFilter(u,"a.building_id")+" AND a.version_id IS NOT NULL";var rows=db.rows("SELECT a.* FROM v_stay_application a WHERE "+filter+" ORDER BY a.updated_at DESC");for(var a:rows){if(u.role().equals("STUDENT")&&Set.of("DRAFT","PENDING_REVIEW","PENDING_EDIT").contains(a.get("current_status"))){var versions=db.rows("SELECT * FROM stay_version WHERE application_id=? ORDER BY version_id DESC LIMIT 1",a.get("application_id"));if(!versions.isEmpty()){a.put("version_id",versions.get(0).get("version_id"));a.put("reason",versions.get(0).get("reason"));}}a.put("dateRanges",a.get("version_id")==null?List.of():db.rows("SELECT start_date startDate,end_date endDate FROM stay_date_range WHERE version_id=? ORDER BY start_date",a.get("version_id")));a.put("reviews",db.rows("SELECT * FROM stay_review WHERE application_id=? ORDER BY review_id",a.get("application_id")));}return rows;}
 private Map<String,Object> locked(long application){return db.one("SELECT * FROM stay_application WHERE application_id=? FOR UPDATE",application);}
 private void access(CurrentUser u,Map<String,Object>a){if(u.role().equals("STUDENT")){if(id(a.get("student_user_id"))!=u.id())throw BizException.forbidden();}else scope.building(u,id(a.get("building_id")));}
 private Map<String,Object> batch(long batch){return db.one("SELECT * FROM stay_batch WHERE batch_id=?",batch);}
 private void mutable(Map<String,Object>a){require(Set.of("DRAFT","PENDING_REVIEW","PENDING_EDIT").contains(a.get("current_status")),"申请已锁定或归档，不能修改");LocalDateTime deadline;if("PENDING_EDIT".equals(a.get("current_status")))deadline=time(a.get("resubmit_deadline"));else deadline=time(db.one("SELECT application_deadline FROM stay_building_rule WHERE batch_id=? AND building_id=?",a.get("batch_id"),a.get("building_id")).get("application_deadline"));require(LocalDateTime.now().isBefore(deadline),"已超过允许提交时间");}
 public static List<Map<String,Object>> validateRanges(Object raw,LocalDate start,LocalDate end){
  require(raw instanceof List<?> && !((List<?>)raw).isEmpty(),"至少填写一个留宿时间段");List<Map<String,Object>> ranges=new ArrayList<>();
  for(Object x:(List<?>)raw){require(x instanceof Map<?,?>,"留宿日期格式无效");Map<?,?> r=(Map<?,?>)x;LocalDate a=date(r.get("startDate")),b=date(r.get("endDate"));require(!b.isBefore(a)&&!a.isBefore(start)&&!b.isAfter(end),"每个留宿时间段必须完全位于开放区间内");ranges.add(Map.of("startDate",a,"endDate",b));}
  ranges.sort(Comparator.comparing(x->(LocalDate)x.get("startDate")));for(int i=1;i<ranges.size();i++)require(((LocalDate)ranges.get(i).get("startDate")).isAfter((LocalDate)ranges.get(i-1).get("endDate")),"留宿时间段不可重叠，共享边界日也算重叠");return ranges;
 }
 private long version(long application,Map<String,Object>b,Map<String,Object>batch,boolean submit){var ranges=validateRanges(b.get("dateRanges"),date(batch.get("open_start_date")),date(batch.get("open_end_date")));long v=db.insert("INSERT INTO stay_version(application_id,reason,submitted_at) VALUES(?,?,?)",application,required(b,"reason"),submit?LocalDateTime.now():null);for(var r:ranges)db.update("INSERT INTO stay_date_range(version_id,start_date,end_date) VALUES(?,?,?)",v,r.get("startDate"),r.get("endDate"));return v;}
 @Transactional public Map<String,Object> save(CurrentUser u,Map<String,Object>b){role(u,"STUDENT");long batchId=id(b.get("batchId"));var batch=batch(batchId);require("OPEN".equals(batch.get("current_status")),"批次未开放");db.one("SELECT user_id FROM sys_user WHERE user_id=? FOR UPDATE",u.id());var old=db.rows("SELECT * FROM stay_application WHERE batch_id=? AND student_user_id=? FOR UPDATE",batchId,u.id());long application;Map<String,Object>a;if(old.isEmpty()){var home=scope.accommodation(u.id());var rule=db.one("SELECT * FROM stay_building_rule WHERE batch_id=? AND building_id=?",batchId,home.get("building_id"));require(LocalDateTime.now().isBefore(time(rule.get("application_deadline"))),"已超过申请截止时间");application=db.insert("INSERT INTO stay_application(batch_id,student_user_id,building_id,current_status) VALUES(?,?,?,'DRAFT')",batchId,u.id(),home.get("building_id"));a=locked(application);}else{a=old.get(0);application=id(a.get("application_id"));mutable(a);}version(application,b,batch,false);db.update("UPDATE stay_application SET updated_at=NOW() WHERE application_id=?",application);db.log(u.id(),"stay","save",application);return Map.of("applicationId",application);}
 @Transactional public void submit(CurrentUser u,long application){role(u,"STUDENT");var a=locked(application);access(u,a);mutable(a);var batch=batch(id(a.get("batch_id")));require("OPEN".equals(batch.get("current_status")),"批次未开放");var v=db.one("SELECT * FROM stay_version WHERE application_id=? ORDER BY version_id DESC LIMIT 1",application);var ranges=db.rows("SELECT start_date startDate,end_date endDate FROM stay_date_range WHERE version_id=?",v.get("version_id"));validateRanges(ranges,date(batch.get("open_start_date")),date(batch.get("open_end_date")));require(v.get("submitted_at")==null,"该版本已经提交");db.update("UPDATE stay_version SET submitted_at=NOW() WHERE version_id=?",v.get("version_id"));String next="PENDING_EDIT".equals(a.get("current_status"))?"UNDER_REVIEW":"PENDING_REVIEW";db.update("UPDATE stay_application SET current_status=? WHERE application_id=?",next,application);notice.managers(id(a.get("building_id")),"留宿申请已提交","申请编号："+application);db.log(u.id(),"stay","submit",application);}
 @Transactional public void withdraw(CurrentUser u,long application){role(u,"STUDENT");var a=locked(application);access(u,a);require("PENDING_REVIEW".equals(a.get("current_status")),"只能撤回尚未锁定的待审核申请");mutable(a);var previous=db.one("SELECT * FROM stay_version WHERE application_id=? ORDER BY version_id DESC LIMIT 1",application);long draft=db.insert("INSERT INTO stay_version(application_id,reason) VALUES(?,?)",application,previous.get("reason"));db.update("INSERT INTO stay_date_range(version_id,start_date,end_date) SELECT ?,start_date,end_date FROM stay_date_range WHERE version_id=?",draft,previous.get("version_id"));db.update("UPDATE stay_application SET current_status='DRAFT' WHERE application_id=?",application);db.log(u.id(),"stay","withdraw",application);}
 @Transactional public void lock(CurrentUser u,long application,boolean lock){role(u,"DORM_MANAGER");var a=locked(application);access(u,a);if(lock){require("PENDING_REVIEW".equals(a.get("current_status")),"只能锁定已提交待审核申请");db.update("UPDATE stay_application SET current_status='UNDER_REVIEW' WHERE application_id=?",application);}else{require("UNDER_REVIEW".equals(a.get("current_status"))&&a.get("resubmit_deadline")==null,"当前申请不允许普通解锁");var r=db.one("SELECT application_deadline FROM stay_building_rule WHERE batch_id=? AND building_id=?",a.get("batch_id"),a.get("building_id"));require(time(r.get("application_deadline")).isAfter(LocalDateTime.now()),"截止后不能通过解锁绕过期限，请使用逾期补录");db.update("UPDATE stay_application SET current_status='PENDING_REVIEW' WHERE application_id=?",application);}db.log(u.id(),"stay",lock?"lock":"unlock",application);}
 @Transactional public void review(CurrentUser u,long application,Map<String,Object>b){role(u,"DORM_MANAGER","ADMIN");var a=locked(application);access(u,a);if(u.role().equals("ADMIN"))require(!"NORMAL".equals(a.get("source")),"普通申请由管辖宿管审核");require("UNDER_REVIEW".equals(a.get("current_status")),"只能审核已锁定的审核中申请");if(a.get("resubmit_deadline")!=null)require(!time(a.get("resubmit_deadline")).isAfter(LocalDateTime.now()),"请在重交截止后统一复审");boolean pass=flag(b,"pass");String reason=pass?text(b,"reason"):required(b,"reason");LocalDateTime deadline=pass?null:time(b.get("resubmitDeadline"));if(!pass)require(deadline.isAfter(LocalDateTime.now()),"重交截止时间必须晚于当前时间");var v=db.one("SELECT version_id FROM stay_version WHERE application_id=? AND submitted_at IS NOT NULL ORDER BY version_id DESC LIMIT 1",application);if(pass){var batch=batch(id(a.get("batch_id")));validateRanges(db.rows("SELECT start_date startDate,end_date endDate FROM stay_date_range WHERE version_id=?",v.get("version_id")),date(batch.get("open_start_date")),date(batch.get("open_end_date")));}db.update("INSERT INTO stay_review(application_id,version_id,reviewer_user_id,result,reason) VALUES(?,?,?,?,?)",application,v.get("version_id"),u.id(),pass?"APPROVED":"RETURNED",reason);db.update("UPDATE stay_application SET current_status=?,review_reason=?,reviewer_user_id=?,reviewed_at=NOW(),resubmit_deadline=? WHERE application_id=?",pass?"APPROVED":"PENDING_EDIT",reason,u.id(),deadline,application);notice.send(List.of(id(a.get("student_user_id"))),"留宿审核结果",pass?"留宿申请已通过":"请修改："+reason+"；重交截止："+deadline);db.log(u.id(),"stay","review",application);}
 @Transactional public Map<String,Object> configure(CurrentUser u,Long batchId,Map<String,Object>b){role(u,"ADMIN");LocalDate start=date(b.get("openStartDate")),end=date(b.get("openEndDate"));require(!end.isBefore(start),"开放区间无效");long batch;if(batchId==null){batch=db.insert("INSERT INTO stay_batch(batch_code,batch_name,open_start_date,open_end_date,application_deadline,instructions,current_status) VALUES(?,?,?,?,?,?,'OPEN')",required(b,"batchCode"),required(b,"batchName"),start,end,start.atStartOfDay(),required(b,"instructions"));}else{batch=batchId;db.one("SELECT batch_id FROM stay_batch WHERE batch_id=? FOR UPDATE",batch);db.update("UPDATE stay_batch SET batch_name=?,open_start_date=?,open_end_date=?,instructions=? WHERE batch_id=?",required(b,"batchName"),start,end,required(b,"instructions"),batch);for(var a:db.rows("SELECT * FROM stay_application WHERE batch_id=? AND current_status IN ('APPROVED','PENDING_REVIEW','UNDER_REVIEW') FOR UPDATE",batch)){db.update("UPDATE stay_application SET current_status='UNDER_REVIEW' WHERE application_id=?",a.get("application_id"));notice.managers(id(a.get("building_id")),"留宿开放区间变更，请复核","申请编号："+a.get("application_id"));notice.send(List.of(id(a.get("student_user_id"))),"留宿开放区间变更",start+" 至 "+end+"，申请等待宿管复核");}}db.log(u.id(),"stay","configure_batch",batch);return Map.of("batchId",batch);}
 @Transactional public void publish(CurrentUser u,long batchId,Map<String,Object>b){role(u,"DORM_MANAGER");long building=id(b.get("buildingId"));scope.building(u,building);var batch=batch(batchId);LocalDateTime deadline=time(b.get("applicationDeadline"));require(deadline.isAfter(LocalDateTime.now())&&deadline.isBefore(date(batch.get("open_end_date")).plusDays(1).atStartOfDay()),"截止时间必须在当前时间之后、开放区间结束之前");db.update("INSERT INTO stay_building_rule(batch_id,building_id,application_deadline,auto_lock) VALUES(?,?,?,?) ON DUPLICATE KEY UPDATE application_deadline=VALUES(application_deadline),auto_lock=VALUES(auto_lock)",batchId,building,deadline,flag(b,"autoLock"));notice.send(db.rows("SELECT student_user_id FROM v_accommodation_current WHERE building_id=?",building).stream().map(x->id(x.get("student_user_id"))).toList(),"留宿申请已开放",batch.get("batch_name")+"；申请截止："+deadline);db.log(u.id(),"stay","publish",batchId);}
 @Transactional public Map<String,Object> supplement(CurrentUser u,Map<String,Object>b){role(u,"DORM_MANAGER","ADMIN");long student=id(b.get("studentUserId")),batchId=id(b.get("batchId"));db.one("SELECT user_id FROM sys_user WHERE user_id=? AND role_code='STUDENT' AND enabled=1 FOR UPDATE",student);var home=scope.accommodation(student);scope.building(u,id(home.get("building_id")));var batch=batch(batchId);require("OPEN".equals(batch.get("current_status")),"批次未开放");if(u.role().equals("DORM_MANAGER")){var rule=db.one("SELECT application_deadline FROM stay_building_rule WHERE batch_id=? AND building_id=?",batchId,home.get("building_id"));require(!time(rule.get("application_deadline")).isAfter(LocalDateTime.now()),"未到截止时间，请由学生正常申请");}var old=db.rows("SELECT * FROM stay_application WHERE batch_id=? AND student_user_id=? FOR UPDATE",batchId,student);long a;if(old.isEmpty())a=db.insert("INSERT INTO stay_application(batch_id,student_user_id,building_id,source,current_status) VALUES(?,?,?,?,'UNDER_REVIEW')",batchId,student,home.get("building_id"),u.role().equals("ADMIN")?"ADMIN_ADDED":"LATE");else{var original=old.get(0);require(Set.of("DRAFT","PENDING_EDIT","ARCHIVED").contains(original.get("current_status")),"已有有效申请，不能重复补录");a=id(original.get("application_id"));db.update("UPDATE stay_application SET source=?,current_status='UNDER_REVIEW',resubmit_deadline=NULL,archived_at=NULL,archive_reason=NULL WHERE application_id=?",u.role().equals("ADMIN")?"ADMIN_ADDED":"LATE",a);}version(a,b,batch,true);db.log(u.id(),"stay","supplement",a);return Map.of("applicationId",a);}
 @Transactional public void tick(){db.update("UPDATE stay_application a JOIN stay_building_rule r ON r.batch_id=a.batch_id AND r.building_id=a.building_id SET a.current_status='UNDER_REVIEW' WHERE a.current_status='PENDING_REVIEW' AND r.auto_lock=1 AND r.application_deadline<=NOW()");for(var a:db.rows("SELECT * FROM stay_application WHERE current_status='PENDING_EDIT' AND resubmit_deadline<=NOW() FOR UPDATE")){db.update("UPDATE stay_application SET current_status='ARCHIVED',archived_at=NOW(),archive_reason='未按期重新提交' WHERE application_id=?",a.get("application_id"));notice.send(List.of(id(a.get("student_user_id"))),"留宿申请归档","未按期重新提交，不计为已完成留宿");}for(var x:db.rows("SELECT application_id FROM v_stay_application WHERE current_status='APPROVED' AND end_date<CURRENT_DATE()")){var a=locked(id(x.get("application_id")));if(!"APPROVED".equals(a.get("current_status")))continue;db.update("UPDATE stay_application SET current_status='COMPLETED',archived_at=NOW(),archive_reason='留宿结束' WHERE application_id=?",a.get("application_id"));notice.send(List.of(id(a.get("student_user_id"))),"留宿已完成","申请已纳入历史留宿记录");}}
}
